def install(skills):
    existing={item['name'] for item in skills.list()}
    added=[]
    for name,(title,requirements,procedure) in PACK.items():
        if name not in existing:
            if len(existing)+len(added)>=50:break
            skills.save(name, COMMON + '\n\n' + procedure)
            added.append(name)
    return added


def describe(items):
    return [{**item, **({'title':PACK[item['name']][0], 'requirements':PACK[item['name']][1], 'kind':'Sakura workflow adaptation'} if item['name'] in PACK else {})} for item in items]


def learn_completed(skills, run, name):
    steps=run.get('steps',[])
    if run.get('status')!='completed' or not steps or any(step.get('status')!='completed' or (step.get('result') or {}).get('ok') is False for step in steps):
        raise ValueError('Choose a successfully completed task with verified tool steps.')
    # Record the procedure, never concrete credentials, document contents or
    # approval tokens from the completed execution.
    tools=[step.get('tool','') for step in steps]
    if any(not isinstance(tool,str) or not tool or len(tool)>160 for tool in tools):raise ValueError('The completed task contains an invalid tool name.')
    text=COMMON+'\n\nA successful task used these tools in order: '+', '.join(tools)+'. Read the new goal and workspace first. Infer fresh arguments from current inputs rather than reusing old private data. Validate each tool schema and result before proceeding, and stop on failure. Previous approvals do not apply to this new task.'
    return skills.save(name,text)
